export const pages = categories.flatMap((category, categoryIndex) => category.topics.map((topic, topicIndex) => {
  const [key, title, situation, goal, keyDocument, turningPoint] = topic;
  const index = categoryIndex * 10 + topicIndex;
  const location = locations[index % locations.length];
  return {
    batch: 1,
    index,
    category,
    key,
    title,
    situation,
    goal,
    keyDocument,
    turningPoint,
    location,
    slug: `saudi-guide-w1-${key}-${location.key}.html`
  };
}));

function escapeHtml(value) {
  return String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}

function list(items, ordered = false) {
  const tag = ordered ? "ol" : "ul";
  const className = ordered ? ' class="document-list"' : "";
  return `<${tag}${className}>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</${tag}>`;
}

