export function generateNationalWave1() {
  if (pages.length !== 100) throw new Error(`Expected 100 pages, found ${pages.length}.`);
  const slugs = new Set(pages.map((page) => page.slug));
  if (slugs.size !== pages.length) throw new Error("Duplicate national wave-one slug.");
  for (const page of pages) writeFileSync(resolve(root, page.slug), render(page), "utf8");
  const rolloutPath = resolve(root, "national-seo-rollout.json");
  let rollout = { updated: contentDate, targetPages: 1000, pagesPerDay: 100, completedBatches: [], publishedPages: 0, remainingPages: 1000, nextBatch: 1 };
  try {
    rollout = { ...rollout, ...JSON.parse(readFileSync(rolloutPath, "utf8")) };
  } catch {
    // A fresh checkout may not have a rollout record yet.
  }
  rollout.updated = rollout.updated > contentDate ? rollout.updated : contentDate;
  rollout.completedBatches = [...new Set([...rollout.completedBatches, 1])].sort((left, right) => left - right);
  rollout.publishedPages = rollout.completedBatches.length * rollout.pagesPerDay;
  rollout.remainingPages = Math.max(rollout.targetPages - rollout.publishedPages, 0);
  rollout.nextBatch = rollout.remainingPages > 0 ? Math.max(...rollout.completedBatches) + 1 : null;
  writeFileSync(rolloutPath, `${JSON.stringify(rollout, null, 2)}\n`, "utf8");
  console.log(`Generated ${pages.length} original national guide pages for batch 1.`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) generateNationalWave1();
